251	fn add_equation_number(
252	    equation_builder: MathRunFrameBuilder,
253	    number: Frame,
254	    number_align: Axes<FixedAlignment>,
255	    equation_align: FixedAlignment,
256	    region_size_x: Abs,
257	    full_number_width: Abs,
258	) -> Frame {
259	    let first =
260	        equation_builder.frames.first().map_or(
261	            (equation_builder.size, Point::zero(), Abs::zero()),
262	            |(frame, pos)| (frame.size(), *pos, frame.baseline()),
263	        );
264	    let last =
265	        equation_builder.frames.last().map_or(
266	            (equation_builder.size, Point::zero(), Abs::zero()),
267	            |(frame, pos)| (frame.size(), *pos, frame.baseline()),
268	        );
269	    let line_count = equation_builder.frames.len();
270	    let mut equation = equation_builder.build_aligned();
271	
272	    let width = if region_size_x.is_finite() {
273	        region_size_x
274	    } else {
275	        equation.width() + 2.0 * full_number_width
276	    };
277	
278	    let is_multiline = line_count >= 2;
279	    let resizing_offset = resize_equation(
280	        &mut equation,
281	        &number,
282	        number_align,
283	        equation_align,
284	        width,
285	        is_multiline,
286	        [first, last],
287	    );
288	    equation.translate(Point::with_x(match (equation_align, number_align.x) {
289	        (FixedAlignment::Start, FixedAlignment::Start) => full_number_width,
290	        (FixedAlignment::End, FixedAlignment::End) => -full_number_width,
291	        _ => Abs::zero(),
292	    }));
293	
294	    let x = match number_align.x {
295	        FixedAlignment::Start => Abs::zero(),
296	        FixedAlignment::End => equation.width() - number.width(),
297	        FixedAlignment::Center => unreachable!(),
298	    };
299	    let y = {
300	        let align_baselines = |(_, pos, baseline): (_, Point, Abs), number: &Frame| {
301	            resizing_offset.y + pos.y + baseline - number.baseline()
302	        };
303	        match number_align.y {
304	            FixedAlignment::Start => align_baselines(first, &number),
305	            FixedAlignment::Center if !is_multiline => align_baselines(first, &number),
306	            // In this case, the center lines (not baselines) of the number frame
307	            // and the equation frame shall be aligned.
308	            FixedAlignment::Center => (equation.height() - number.height()) / 2.0,
309	            FixedAlignment::End => align_baselines(last, &number),
310	        }
311	    };
312	
313	    equation.push_frame(Point::new(x, y), number);
314	    equation
315	}
