553	/// Ignore a MathML HTML element during paged export.
554	fn layout_mathml(
555	    item: &MathmlItem,
556	    ctx: &mut MathContext,
557	    _styles: StyleChain,
558	    _props: &MathProperties,
559	) -> SourceResult<()> {
560	    ctx.engine.sink.warn(warning!(
