617	/// Get the current base font.
618	fn get_font(
619	    world: Tracked<dyn World + '_>,
620	    styles: StyleChain,
621	    span: Span,
622	) -> SourceResult<FontInstance> {
623	    let variant = variant(styles);
624	    let size = styles.resolve(TextElem::size);
625	    let variations = styles.get_cloned(TextElem::variations);
626	    families(styles)
627	        .find_map(|family| {
628	            world
629	                .book()
630	                .select(family.as_str(), variant)
631	                .and_then(|id| world.font(id))
632	                .filter(|_| family.covers().is_none())
633	                .map(|font| font.instantiate(variant, size, &variations))
634	        })
635	        .ok_or("no font could be found")
636	        .at(span)
637	}
638	
639	/// Check if the top-level base font has a MATH table.
640	fn warn_non_math_font(font: &Font, engine: &mut Engine, span: Span) {
641	    if !font.info().flags.contains(FontFlags::MATH) {
642	        engine.sink.warn(warning!(
643	            span,
644	            "current font is not designed for math";
645	            hint: "rendering may be poor";
646	        ));
647	    }
648	}
