24	/// Maximum number of times extenders can be repeated.
25	const MAX_REPEATS: usize = 1024;
26	
27	#[derive(Clone)]
28	pub struct GlyphFragment {
29	    // Text stuff.
30	    pub(super) item: TextItem,
31	    // Math stuff.
32	    pub(super) size: Size,
33	    baseline: Option<Abs>,
34	    pub(super) italics_correction: Abs,
35	    pub(super) accent_attach: (Abs, Abs),
36	    pub(super) math_size: MathSize,
37	    pub class: MathClass,
38	    pub(super) extended_shape: bool,
39	    pub(super) stretchable_axes: Axes<bool>,
40	    // External frame stuff.
41	    modifiers: FrameModifiers,
42	    shift: Abs,
43	    align: Abs,
44	}
45	
46	impl GlyphFragment {
47	    /// Creates a synthetic glyph fragment from the given character.
48	    pub fn synthetic(
49	        engine: &mut Engine,
50	        styles: StyleChain,
51	        c: char,
52	        span: Span,
53	    ) -> Option<Self> {
54	        let class = default_math_class(c).unwrap_or(MathClass::Normal);
55	        let math_size = styles.get(EquationElem::size);
56	        Self::base(
57	            engine.world,
58	            styles,
59	            &features(styles),
60	            c.encode_utf8(&mut [0; 4]),
61	            class,
62	            math_size,
63	        )
64	        .map(|glyph| glyph.with_span(span))
65	    }
66	
67	    /// Creates a glyph fragment from the given text, stretching it if needed.
68	    pub fn new(
69	        engine: &mut Engine,
70	        text: &str,
71	        stretch: &Stretch,
72	        styles: StyleChain,
73	        props: &MathProperties,
74	        class: MathClass,
75	    ) -> Option<GlyphFragment> {
76	        let PlannedGlyph { mut glyph, action } =
77	            Self::planned(engine.world, styles, text, class, props.size, *stretch)?
78	                .with_span(props.span);
79	
80	        match action {
81	            Action::Stretch { axis, target, short_fall } => {
82	                glyph.stretch(engine, target, short_fall, axis);
83	                if axis == Axis::Y {
84	                    glyph.center_on_axis();
85	                }
86	            }
87	            Action::WarnBothAxes => {
88	                // As far as we know, there aren't any glyphs that have both
89	                // vertical and horizontal constructions. So for the time
90	                // being, we will assume that a glyph cannot have both.
91	                engine.sink.warn(warning!(
92	                   props.span,
93	                   "glyph has both vertical and horizontal constructions";
94	                   hint: "this is probably a font bug";
95	                   hint: "please file an issue at https://github.com/typst/typst/issues";
96	                ));
97	            }
98	            Action::Keep | Action::Fallback => {}
99	        }
100	
101	        Some(glyph)
102	    }
103	
104	    #[comemo::memoize]
105	    fn planned(
106	        world: Tracked<dyn World + '_>,
107	        styles: StyleChain,
108	        text: &str,
109	        class: MathClass,
110	        math_size: MathSize,
111	        stretch: Stretch,
112	    ) -> Option<PlannedGlyph> {
113	        let features = features(styles);
114	        let shape = |feats: &[rustybuzz::Feature]| {
115	            Self::base(world, styles, feats, text, class, math_size)
116	        };
117	
118	        let mut glyph = shape(&features)?;
119	        let mut action = decide(&glyph, &stretch);
120	
121	        // If the initial glyph isn't sufficient, keep retrying shaping, by
122	        // removing `ssty` and `flac` features, until one satisfies the stretch
123	        // requirements (or until we exhaust them all, in which case we keep
124	        // the original glyph, unstretched)
125	        if matches!(action, Action::Fallback) {
126	            shaping::feat_fallback(features, |feats| {
127	                let Some(new) = shape(feats) else { return false };
128	                match decide(&new, &stretch) {
129	                    Action::Fallback => false,
130	                    other => {
131	                        glyph = new;
132	                        action = other;
133	                        true
134	                    }
135	                }
136	            });
137	        }
138	
139	        Some(PlannedGlyph { glyph, action })
140	    }
141	
142	    #[comemo::memoize]
143	    fn base(
144	        world: Tracked<dyn World + '_>,
145	        styles: StyleChain,
146	        features: &[rustybuzz::Feature],
147	        text: &str,
148	        class: MathClass,
149	        math_size: MathSize,
150	    ) -> Option<GlyphFragment> {
151	        let shaped = shaping::shape(world, styles, features, text)?;
152	        Some(Self::from_shaped(styles, text.into(), class, math_size, shaped))
153	    }
154	
155	    /// Construct a glyph fragment from the shaped text.
156	    fn from_shaped(
157	        styles: StyleChain,
158	        text: EcoString,
159	        class: MathClass,
160	        math_size: MathSize,
161	        shaped: (FontInstance, Vec<Glyph>),
162	    ) -> GlyphFragment {
163	        let (font, glyphs) = shaped;
164	        let stretchable_axes = stretch_axes(&font, glyphs[0].id);
165	
166	        let item = TextItem {
167	            text,
168	            font,
169	            size: styles.resolve(TextElem::size),
170	            fill: styles.get_ref(TextElem::fill).as_decoration(),
171	            stroke: styles.resolve(TextElem::stroke).map(|s| s.unwrap_or_default()),
172	            lang: styles.get(TextElem::lang),
173	            region: styles.get(TextElem::region),
174	            glyphs,
175	        };
176	
177	        let mut fragment = Self {
178	            item,
179	            // Math
180	            math_size,
181	            class,
182	            stretchable_axes,
183	            // Math in need of updating.
184	            extended_shape: false,
185	            italics_correction: Abs::zero(),
186	            accent_attach: (Abs::zero(), Abs::zero()),
187	            size: Size::zero(),
188	            baseline: None,
189	            // Misc
190	            align: Abs::zero(),
191	            shift: styles.resolve(TextElem::baseline),
192	            modifiers: FrameModifiers::get_in(styles),
193	        };
194	        fragment.update_glyph();
195	        fragment
196	    }
197	
198	    fn with_span(mut self, span: Span) -> Self {
199	        for glyph in &mut self.item.glyphs {
200	            glyph.span = (span, 0);
201	        }
202	        self
203	    }
204	
205	    /// Sets element id and boxes in appropriate way without changing other
206	    /// styles. This is used to replace the glyph with a stretch variant.
207	    fn update_glyph(&mut self) {
208	        let id = GlyphId(self.item.glyphs[0].id);
209	
210	        let extended_shape = is_extended_shape(&self.item.font, id);
211	        let italics = italics_correction(&self.item.font, id).unwrap_or_default();
212	        let width = self.item.width();
213	        if !extended_shape {
214	            self.item.glyphs[0].x_advance += italics;
215	        }
216	        let italics = italics.at(self.item.size);
217	
218	        let (ascent, descent) =
219	            ascent_descent(&self.item.font, id).unwrap_or((Em::zero(), Em::zero()));
220	
221	        // The fallback for accents is half the width plus or minus the italics
222	        // correction. This is similar to how top and bottom attachments are
223	        // shifted. For bottom accents we do not use the accent attach of the
224	        // base as it is meant for top acccents.
225	        let top_accent_attach = accent_attach(&self.item.font, id)
226	            .map(|x| x.at(self.item.size))
227	            .unwrap_or((width + italics) / 2.0);
228	        let bottom_accent_attach = (width - italics) / 2.0;
229	
230	        self.baseline = Some(ascent.at(self.item.size));
231	        self.size = Size::new(
232	            self.item.width(),
233	            ascent.at(self.item.size) + descent.at(self.item.size),
234	        );
235	        self.italics_correction = italics;
236	        self.accent_attach = (top_accent_attach, bottom_accent_attach);
237	        self.extended_shape = extended_shape;
238	    }
239	
240	    fn baseline(&self) -> Abs {
241	        self.ascent()
242	    }
243	
244	    /// The distance from the baseline to the top of the frame.
245	    pub fn ascent(&self) -> Abs {
246	        self.baseline.unwrap_or(self.size.y)
247	    }
248	
249	    /// The distance from the baseline to the bottom of the frame.
250	    pub fn descent(&self) -> Abs {
251	        self.size.y - self.ascent()
252	    }
253	
254	    pub(super) fn into_frame(self) -> Frame {
255	        let mut frame = Frame::soft(self.size);
256	        frame.set_baseline(self.baseline());
257	        frame.push(
258	            Point::with_y(self.ascent() + self.shift + self.align),
259	            FrameItem::Text(self.item),
260	        );
261	        frame.modify(&self.modifiers);
262	        frame
263	    }
264	
265	    /// Try to stretch a glyph to a desired width or height.
266	    ///
267	    /// The resulting frame may not have the exact desired width or height.
268	    fn stretch(&mut self, engine: &mut Engine, target: Abs, short_fall: Abs, axis: Axis) {
269	        // If the base glyph is good enough, use it.
270	        let advance = self.stretch_advance(axis);
271	        let short_target = target - short_fall;
272	        if short_target <= advance {
273	            return;
274	        }
275	
276	        let id = GlyphId(self.item.glyphs[0].id);
277	        let font = self.item.font.clone();
278	        let Some(construction) = glyph_construction(&font, id, axis) else { return };
279	
280	        // Search for a pre-made variant with a good advance.
281	        let mut best_id = id;
282	        let mut best_advance = advance;
283	        for variant in construction.variants {
284	            best_id = variant.variant_glyph;
285	            best_advance =
286	                self.item.font.to_em(variant.advance_measurement).at(self.item.size);
287	            if short_target <= best_advance {
288	                break;
289	            }
290	        }
291	
292	        // This is either good or the best we've got.
293	        if short_target <= best_advance || construction.assembly.is_none() {
294	            self.item.glyphs = vec![Glyph {
295	                id: best_id.0,
296	                x_advance: self.item.font.x_advance(best_id.0).unwrap_or_default(),
297	                x_offset: Em::zero(),
298	                y_advance: self.item.font.y_advance(best_id.0).unwrap_or_default(),
299	                y_offset: Em::zero(),
300	                range: self.item.glyphs[0].range.clone(),
301	                span: self.item.glyphs[0].span,
302	            }];
303	            self.update_glyph();
304	            return;
305	        }
306	
307	        // Assemble from parts.
308	        let assembly = construction.assembly.unwrap();
309	        let min_overlap = min_connector_overlap(&self.item.font)
310	            .unwrap_or_default()
311	            .at(self.item.size);
312	        assemble(engine, self, assembly, min_overlap, target, axis);
313	    }
314	
315	    /// Advance of the glyph along the given axis used during stretching.
316	    fn stretch_advance(&self, axis: Axis) -> Abs {
317	        let mut advance = self.size.get(axis);
318	        if axis == Axis::X && !self.extended_shape {
319	            // For consistency, we subtract the italics correction from the
320	            // glyph's width if it was added in `update_glyph`.
321	            advance -= self.italics_correction;
322	        }
323	        advance
324	    }
325	
326	    /// Vertically adjust the fragment's frame so that it is centered
327	    /// on the axis.
328	    pub fn center_on_axis(&mut self) {
329	        self.align_on_axis(VAlignment::Horizon);
330	    }
331	
332	    /// Vertically adjust the fragment's frame so that it is aligned
333	    /// to the given alignment on the axis.
334	    fn align_on_axis(&mut self, align: VAlignment) {
335	        let h = self.size.y;
336	        let axis = self.item.font.math().axis_height.at(self.item.size);
337	        self.align += self.baseline();
338	        self.baseline = Some(align.inv().position(h + axis * 2.0));
339	        self.align -= self.baseline();
340	    }
341	}
342	
343	impl Debug for GlyphFragment {
344	    fn fmt(&self, f: &mut Formatter<'_>) -> fmt::Result {
345	        write!(f, "GlyphFragment({:?})", self.item.text)
346	    }
347	}
348	
349	#[derive(Clone)]
350	struct PlannedGlyph {
351	    glyph: GlyphFragment,
352	    action: Action,
353	}
354	
355	impl PlannedGlyph {
356	    fn with_span(mut self, span: Span) -> Self {
357	        self.glyph = self.glyph.with_span(span);
358	        self
359	    }
360	}
361	
362	/// How to proceed with the freshly-shaped glyph fragment.
363	#[derive(Clone, Copy)]
364	enum Action {
365	    /// Use this glyph as-is (no stretching is needed).
366	    Keep,
367	    /// Use this glyph and stretch it with the given information.
368	    Stretch { axis: Axis, target: Abs, short_fall: Abs },
369	    /// Use this glyph, but warn that it claims stretchability on both axes.
370	    WarnBothAxes,
371	    /// The glyph isn't stretchable on the axes we need and isn't wide enough
372	    /// to skip stretching (try falling back without some features).
373	    Fallback,
374	}
375	
376	/// Decide how to proceed with the freshly-shaped glyph fragment based on the
377	/// stretch required.
378	fn decide(glyph: &GlyphFragment, stretch: &Stretch) -> Action {
379	    /// The glyph's status for the stretch request on a single axis.
380	    enum AxisStatus {
381	        /// No stretching needed (none requested, or the glyph is already wide
382	        /// enough).
383	        Sufficient,
384	        /// The glyph is stretchable on this axis.
385	        Stretchable { target: Abs, short_fall: Abs },
386	        /// Stretching is needed but the glyph isn't stretchable and isn't wide
387	        /// enough (fallback and retry).
388	        Fallback,
389	    }
390	
391	    let font = &glyph.item.font;
392	    let id = glyph.item.glyphs[0].id;
393	    let axes = glyph.stretchable_axes;
394	
395	    let assess = |axis| {
396	        let Some((target, short_fall)) = resolve_stretch(glyph, stretch, axis) else {
397	            return AxisStatus::Sufficient;
398	        };
399	
400	        if axes.get(axis) {
401	            return AxisStatus::Stretchable { target, short_fall };
402	        }
403	        // Glyph isn't stretchable on this axis, but might be wide enough.
404	
405	        let mut advance = glyph.stretch_advance(axis);
406	
407	        // Combining marks (e.g. accent glyphs) typically have zero advance in
408	        // `hmtx`, so the advance above is no good. We explicitly compute the
409	        // bounding box, just in case.
410	        if let Some(bbox) = font.ttf().glyph_bounding_box(GlyphId(id)) {
411	            let extents = Axes::new(
412	                font.to_em(bbox.x_max - bbox.x_min),
413	                font.to_em(bbox.y_max - bbox.y_min),
414	            );
415	            advance.set_max(extents.get(axis).at(glyph.item.size));
416	        }
417	
418	        if target - short_fall <= advance {
419	            AxisStatus::Sufficient
420	        } else {
421	            AxisStatus::Fallback
422	        }
423	    };
424	
425	    match (assess(Axis::X), assess(Axis::Y)) {
426	        (AxisStatus::Stretchable { .. }, AxisStatus::Stretchable { .. }) => {
427	            Action::WarnBothAxes
428	        }
429	        (AxisStatus::Stretchable { target, short_fall }, _) => {
430	            Action::Stretch { axis: Axis::X, target, short_fall }
431	        }
432	        (_, AxisStatus::Stretchable { target, short_fall }) => {
433	            Action::Stretch { axis: Axis::Y, target, short_fall }
434	        }
435	        (AxisStatus::Sufficient, AxisStatus::Sufficient) => Action::Keep,
436	        _ => Action::Fallback,
437	    }
438	}
439	
440	/// Returns the absolute target and short fall of the stretch along the given
441	/// axis, if it exists.
442	fn resolve_stretch(
443	    glyph: &GlyphFragment,
444	    stretch: &Stretch,
445	    axis: Axis,
446	) -> Option<(Abs, Abs)> {
447	    let stretch = stretch.resolve(axis)?;
448	    let relative_to_size = stretch.relative_to.unwrap_or_else(|| {
449	        if axis == Axis::Y
450	            && glyph.class == MathClass::Large
451	            && glyph.math_size == MathSize::Display
452	        {
453	            glyph.item.font.math().display_operator_min_height.at(glyph.item.size)
454	        } else {
455	            glyph.size.get(axis)
456	        }
457	    });
458	
459	    let target = stretch.target.relative_to(relative_to_size);
460	    let short_fall = stretch.short_fall.at(stretch.font_size.unwrap_or(glyph.item.size));
461	    Some((target, short_fall))
462	}
463	
464	fn ascent_descent(font: &FontInstance, id: GlyphId) -> Option<(Em, Em)> {
465	    let bbox = font.ttf().glyph_bounding_box(id)?;
466	    Some((font.to_em(bbox.y_max), -font.to_em(bbox.y_min)))
467	}
468	
469	/// Look up the italics correction for a glyph.
470	fn italics_correction(font: &FontInstance, id: GlyphId) -> Option<Em> {
471	    font.ttf()
472	        .tables()
473	        .math?
474	        .glyph_info?
475	        .italic_corrections?
476	        .get(id)
477	        .map(|value| font.to_em(value.value))
478	}
479	
480	/// Loop up the top accent attachment position for a glyph.
481	fn accent_attach(font: &FontInstance, id: GlyphId) -> Option<Em> {
482	    font.ttf()
483	        .tables()
484	        .math?
485	        .glyph_info?
486	        .top_accent_attachments?
487	        .get(id)
488	        .map(|value| font.to_em(value.value))
489	}
490	
491	/// Look up whether a glyph is an extended shape.
492	fn is_extended_shape(font: &FontInstance, id: GlyphId) -> bool {
493	    font.ttf()
494	        .tables()
495	        .math
496	        .and_then(|math| math.glyph_info)
497	        .and_then(|glyph_info| glyph_info.extended_shapes)
498	        .and_then(|coverage| coverage.get(id))
499	        .is_some()
500	}
501	
502	/// Look up a kerning value at a specific corner and height.
503	pub(super) fn kern_at_height(
504	    font: &FontInstance,
505	    id: GlyphId,
506	    corner: Corner,
507	    height: Em,
508	) -> Option<Em> {
509	    let kerns = font.ttf().tables().math?.glyph_info?.kern_infos?.get(id)?;
510	    let kern = match corner {
511	        Corner::TopLeft => kerns.top_left,
512	        Corner::TopRight => kerns.top_right,
513	        Corner::BottomRight => kerns.bottom_right,
514	        Corner::BottomLeft => kerns.bottom_left,
515	    }?;
516	
517	    let mut i = 0;
518	    while i < kern.count() && height > font.to_em(kern.height(i)?.value) {
519	        i += 1;
520	    }
521	
522	    Some(font.to_em(kern.kern(i)?.value))
523	}
524	
525	fn stretch_axes(font: &FontInstance, id: u16) -> Axes<bool> {
526	    let id = GlyphId(id);
527	    let horizontal = font
528	        .ttf()
529	        .tables()
530	        .math
531	        .and_then(|math| math.variants)
532	        .and_then(|variants| variants.horizontal_constructions.get(id))
533	        .is_some();
534	    let vertical = font
535	        .ttf()
536	        .tables()
537	        .math
538	        .and_then(|math| math.variants)
539	        .and_then(|variants| variants.vertical_constructions.get(id))
540	        .is_some();
541	
542	    Axes::new(horizontal, vertical)
543	}
544	
545	fn min_connector_overlap(font: &FontInstance) -> Option<Em> {
546	    font.ttf()
547	        .tables()
548	        .math?
549	        .variants
550	        .map(|variants| font.to_em(variants.min_connector_overlap))
551	}
552	
553	fn glyph_construction(
554	    font: &FontInstance,
555	    id: GlyphId,
556	    axis: Axis,
557	) -> Option<GlyphConstruction<'_>> {
558	    font.ttf()
559	        .tables()
560	        .math?
561	        .variants
562	        .map(|variants| match axis {
563	            Axis::X => variants.horizontal_constructions,
564	            Axis::Y => variants.vertical_constructions,
565	        })?
566	        .get(id)
567	}
568	
569	/// Assemble a glyph from parts.
570	fn assemble(
571	    engine: &mut Engine,
572	    base: &mut GlyphFragment,
573	    assembly: GlyphAssembly,
574	    min_overlap: Abs,
575	    target: Abs,
576	    axis: Axis,
577	) {
578	    // Determine the number of times the extenders need to be repeated as well
579	    // as a ratio specifying how much to spread the parts apart
580	    // (0 = maximal overlap, 1 = minimal overlap).
581	    let mut full;
582	    let mut ratio;
583	    let mut repeat = 0;
584	    loop {
585	        full = Abs::zero();
586	        ratio = 0.0;
587	
588	        let mut parts = parts(assembly, repeat).peekable();
589	        let mut growable = Abs::zero();
590	
591	        while let Some(part) = parts.next() {
592	            let mut advance = base.item.font.to_em(part.full_advance).at(base.item.size);
593	            if let Some(next) = parts.peek() {
594	                let max_overlap = base
595	                    .item
596	                    .font
597	                    .to_em(part.end_connector_length.min(next.start_connector_length))
598	                    .at(base.item.size);
599	                if max_overlap < min_overlap {
600	                    // This condition happening is indicative of a bug in the
601	                    // font.
602	                    engine.sink.warn(warning!(
603	                       base.item.glyphs[0].span.0,
604	                       "glyph has assembly parts with overlap less than minConnectorOverlap";
605	                       hint: "its rendering may appear broken - this is probably a font bug";
606	                       hint: "please file an issue at https://github.com/typst/typst/issues";
607	                    ));
608	                }
609	
610	                advance -= max_overlap;
611	                // In case we have that max_overlap < min_overlap, ensure we
612	                // don't decrease the value of growable.
613	                growable += (max_overlap - min_overlap).max(Abs::zero());
614	            }
615	
616	            full += advance;
617	        }
618	
619	        if full < target {
620	            let delta = target - full;
621	            ratio = (delta / growable).min(1.0);
622	            full += ratio * growable;
623	        }
624	
625	        if target <= full || repeat >= MAX_REPEATS {
626	            break;
627	        }
628	
629	        repeat += 1;
630	    }
631	
632	    let mut glyphs = vec![];
633	    let mut parts = parts(assembly, repeat).peekable();
634	    while let Some(part) = parts.next() {
635	        let mut advance = base.item.font.to_em(part.full_advance).at(base.item.size);
636	        if let Some(next) = parts.peek() {
637	            let max_overlap = base
638	                .item
639	                .font
640	                .to_em(part.end_connector_length.min(next.start_connector_length))
641	                .at(base.item.size);
642	            advance -= max_overlap;
643	            advance += ratio * (max_overlap - min_overlap);
644	        }
645	        let (x_advance, y_advance, y_offset) = match axis {
646	            Axis::X => (Em::from_abs(advance, base.item.size), Em::zero(), Em::zero()),
647	            Axis::Y => (
648	                Em::zero(),
649	                Em::from_abs(advance, base.item.size),
650	                // Glyph parts used in vertical assemblies are typically aligned
651	                // at the vertical origin. This way, they combine properly when
652	                // drawn consecutively, as required by the MATH table spec.
653	                //
654	                // However, in some fonts, they aren't. To still have them align
655	                // properly, we are vertically offsetting such glyphs by their
656	                // bounding-box computed descent. (Positive descent means that
657	                // a glyph extends below the baseline and then we must move it
658	                // up for it to align properly. `y_advance` is Y-up, so that
659	                // matches up.)
660	                ascent_descent(&base.item.font, part.glyph_id)
661	                    .map(|x| x.1)
662	                    .unwrap_or_default(),
663	            ),
664	        };
665	        glyphs.push(Glyph {
666	            id: part.glyph_id.0,
667	            x_advance,
668	            x_offset: Em::zero(),
669	            y_advance,
670	            y_offset,
671	            range: base.item.glyphs[0].range.clone(),
672	            span: base.item.glyphs[0].span,
673	        });
674	    }
675	
676	    match axis {
677	        Axis::X => {
678	            base.size.x = full;
679	            let (ascent, descent) = glyphs
680	                .iter()
681	                .filter_map(|glyph| ascent_descent(&base.item.font, GlyphId(glyph.id)))
682	                .reduce(|(ma, md), (a, d)| (ma.max(a), md.max(d)))
683	                .unwrap_or((Em::zero(), Em::zero()));
684	            base.baseline = Some(ascent.at(base.item.size));
685	            base.size.y = (ascent + descent).at(base.item.size);
686	        }
687	        Axis::Y => {
688	            base.baseline = None;
689	            base.size.y = full;
690	            base.size.x = glyphs
691	                .iter()
692	                .map(|glyph| base.item.font.x_advance(glyph.id).unwrap_or_default())
693	                .max()
694	                .unwrap_or_default()
695	                .at(base.item.size);
696	        }
697	    }
698	
699	    base.item.glyphs = glyphs;
700	    base.italics_correction = base
701	        .item
702	        .font
703	        .to_em(assembly.italics_correction.value)
704	        .at(base.item.size);
705	    if axis == Axis::X {
706	        base.accent_attach = (full / 2.0, full / 2.0);
707	    }
708	    base.extended_shape = true;
709	}
710	
711	/// Return an iterator over the assembly's parts with extenders repeated the
712	/// specified number of times.
713	fn parts(
714	    assembly: GlyphAssembly<'_>,
715	    repeat: usize,
716	) -> impl Iterator<Item = GlyphPart> + '_ {
717	    assembly.parts.into_iter().flat_map(move |part| {
718	        let count = if part.part_flags.extender() { repeat } else { 1 };
719	        std::iter::repeat_n(part, count)
720	    })
721	}
