17	/// A list of math fragments between alignment points and/or linebreaks.
18	///
19	/// For multiline equations this represents a distinct "cell", the list of
20	/// fragments at a specific row and column. For tables, this represents a
21	/// "sub-column", one of the parts that make up a cell in a table since
22	/// alignment points can be used to align fragments within a cell for an
23	/// individual column.
24	pub type MathRun = Vec<MathFragment>;
