96	/// A single row to be laid out in multiline math.
97	pub struct RowLayout {
98	    /// The row's content, split by alignment points.
99	    pub cells: Vec<MathRun>,
100	    /// The ascent and descent that the row's final frame should have.
101	    pub frame_height: (Abs, Abs),
102	    /// The ascent and descent that should be used for this row when stacking
103	    /// rows together. If not specified,
104	    /// [`frame_height`](RowLayout::frame_height) is used instead.
105	    ///
106	    /// This is used in table layout, where within each column there are rows
107	    /// which need to be alignment. But when positioning rows together we need
108	    /// to align them based on the sizes of all columns of the table.
109	    pub row_height: Option<(Abs, Abs)>,
110	}
111	
112	/// Build and stack line frames for rows with aligned columns.
113	pub fn stack_rows(
114	    rows: impl IntoIterator<Item = RowLayout>,
115	    widths: &[Abs],
116	    alternator: LeftRightAlternator,
117	    align: FixedAlignment,
118	    leading: Abs,
119	    start_y: Abs,
120	) -> MathRunFrameBuilder {
121	    let (points, total_width) = cumulative_alignment_points(widths);
122	    let has_alignment = !points.is_empty();
123	
124	    let rows = rows.into_iter().map(|row| {
125	        let frame =
126	            row_into_line_frame(row.cells, &points, alternator, Some(row.frame_height));
127	        (frame, row.row_height.unwrap_or(row.frame_height))
128	    });
129	
130	    let mut frames = Vec::new();
131	    let mut size = Size::new(Abs::zero(), start_y);
132	
133	    for (i, (sub, (row_ascent, row_descent))) in rows.into_iter().enumerate() {
134	        if i > 0 {
135	            size.y += leading;
136	        }
137	        let mut pos = Point::with_y(size.y + row_ascent - sub.ascent());
138	        if !has_alignment {
139	            pos.x = align.position(total_width - sub.width());
140	        }
141	        size.x.set_max(sub.width());
142	        size.y += row_ascent + row_descent;
143	        frames.push((sub, pos));
144	    }
145	
146	    MathRunFrameBuilder { size, frames }
147	}
