15	/// Lays out a [`TextItem`].
16	#[typst_macros::time(name = "math text layout", span = props.span)]
17	pub fn layout_text(
18	    item: &TextItem,
19	    ctx: &mut MathContext,
20	    styles: StyleChain,
21	    props: &MathProperties,
22	) -> SourceResult<()> {
23	    let text = &item.text;
24	    let span = props.span;
25	    let elem = TextElem::packed(text).spanned(span);
26	
27	    // There isn't a natural width for a paragraph in a math environment;
28	    // because it will be placed somewhere probably not at the left margin
29	    // it will overflow. So emulate an `hbox` instead and allow the
30	    // paragraph to extend as far as needed.
31	    let frame = crate::inline::layout_inline(
32	        ctx.engine,
33	        &[(&elem, styles)],
34	        &mut item.locator.relayout().split(),
35	        styles,
36	        Size::splat(Abs::inf()),
37	        false,
38	    )?
39	    .into_frame();
40	    ctx.push(FrameFragment::new(props, styles, frame).with_text_like(true));
41	    Ok(())
42	}
