44	/// Lays out a [`NumberItem`].
45	#[typst_macros::time(name = "math number layout", span = props.span)]
46	pub fn layout_number(
47	    item: &NumberItem,
48	    ctx: &mut MathContext,
49	    styles: StyleChain,
50	    props: &MathProperties,
51	) -> SourceResult<()> {
52	    let text = &item.text;
53	    let span = props.span;
54	    // Small optimization for numbers. Note that this lays out slightly
55	    // differently to normal text and is worth re-evaluating in the future.
56	    let mut fragments = vec![];
57	    for c in text.chars() {
58	        if let Some(glyph) = GlyphFragment::synthetic(ctx.engine, styles, c, span) {
59	            fragments.push(glyph.into());
60	        }
61	    }
62	    let frame = fragments.into_frame();
63	    ctx.push(FrameFragment::new(props, styles, frame).with_text_like(true));
64	    Ok(())
65	}
