67	/// Layout a single character in the math font.
68	#[typst_macros::time(name = "math glyph layout", span = props.span)]
69	pub fn layout_glyph(
70	    item: &GlyphItem,
71	    ctx: &mut MathContext,
72	    styles: StyleChain,
73	    props: &MathProperties,
74	) -> SourceResult<()> {
75	    let flac;
76	    let styles = if item.flac.get() {
77	        flac = style_flac();
78	        styles.chain(&flac)
79	    } else {
80	        styles
81	    };
82	
83	    let dtls;
84	    let (styles, text): (_, EcoString) =
85	        if item.text.chars().any(|c| try_dotless(c).is_some())
86	            && has_dtls_feat(ctx.font())
87	        {
88	            dtls = style_dtls();
89	            let variant = styles.get(EquationElem::variant);
90	            let bold = styles.get(EquationElem::bold);
91	            let italic = styles.get(EquationElem::italic);
92	            let text = item
93	                .text
94	                .chars()
95	                .flat_map(|mut c| {
96	                    if let Some(d) = try_dotless(c) {
97	                        c = d;
98	                    }
99	                    to_style(c, MathStyle::select(c, variant, bold, italic))
100	                })
101	                .collect();
102	            (styles.chain(&dtls), text)
103	        } else {
104	            (styles, item.text.clone())
105	        };
106	
107	    if let Some(mut glyph) = GlyphFragment::new(
108	        ctx.engine,
109	        &text,
110	        &item.stretch.get(),
111	        styles,
112	        props,
113	        item.class,
114	    ) {
115	        if glyph.class == MathClass::Large {
